WITH valid AS (SELECT *, CONCAT_WS('-', status, method) AS status_method_key, ROUND(amount * 0.85, 2) AS amount_adjusted FROM payments WHERE paid_at >= TO_TIMESTAMP('2023-05-10 06:00:00') AND order_id IS NOT NULL) SELECT d.status AS order_status, src.status AS payment_status, COUNT(*) AS num_rows, MAX(src.amount) AS max_amount, SUM(src.amount_adjusted) AS total_amount_adjusted FROM valid src INNER JOIN orders d ON src.order_id = d.id GROUP BY GROUPING SETS ((d.status, src.status), (d.status), ()) ORDER BY max_amount DESC;
